struct Value {
    int v;
    explicit Value(int x) : v(x) {}
};

// Direct initialization (Traditional constructor call)
Value v1(10);

// Direct list initialization (Uniform initialization)
Value v2{20};

// Direct aggregate initialization
struct Point { int x, y; };
Point p1{1, 2};
int arr[]{3, 4};

// Direct reference initialization
int x = 5;
int& r(x);

// C++20 designated initialization (aggregate)
struct Color { int r; int g; };
Color c{.g=128, .r=255};
